#!/usr/bin/env node
/**
 * Registers the Android app as a handler for PDFs and Office documents.
 *
 * Capacitor's generated manifest only declares a launcher activity, so the app
 * never appears in Android's "Open with" or share sheets. There is no way to
 * express extra intent filters through capacitor.config.ts, and `android/` is
 * regenerated by `cap add`, so this patches the manifest instead and runs as
 * part of native:init and native:sync.
 *
 * Idempotent: it looks for the marker comment and leaves an already patched
 * manifest alone.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const manifestPath = path.join(
  root,
  'android/app/src/main/AndroidManifest.xml'
);

const MARKER = 'BentoPDF document intent filters';

/**
 * A filter with only a mimeType implicitly matches the content: and file:
 * schemes, which is what file managers and share sheets actually send.
 */
const MIME_TYPES = [
  // PDF - the main event.
  'application/pdf',
  // Word
  'application/msword',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/vnd.oasis.opendocument.text',
  'application/rtf',
  'text/rtf',
  // Excel
  'application/vnd.ms-excel',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  'application/vnd.oasis.opendocument.spreadsheet',
  // PowerPoint
  'application/vnd.ms-powerpoint',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  'application/vnd.oasis.opendocument.presentation',
];

const dataElements = (indent) =>
  MIME_TYPES.map((type) => `${indent}<data android:mimeType="${type}" />`).join(
    '\n'
  );

const filters = () => {
  const i = '                ';
  return `
            <!-- ${MARKER} (scripts/native-patch-android.mjs) -->
            <intent-filter>
                <action android:name="android.intent.action.VIEW" />
                <category android:name="android.intent.category.DEFAULT" />
                <category android:name="android.intent.category.BROWSABLE" />
${dataElements(i)}
            </intent-filter>
            <intent-filter>
                <action android:name="android.intent.action.SEND" />
                <category android:name="android.intent.category.DEFAULT" />
${dataElements(i)}
            </intent-filter>
            <intent-filter>
                <action android:name="android.intent.action.SEND_MULTIPLE" />
                <category android:name="android.intent.category.DEFAULT" />
${dataElements(i)}
            </intent-filter>
`;
};

if (!fs.existsSync(manifestPath)) {
  console.log('[native-patch] No Android project yet - nothing to patch.');
  process.exit(0);
}

const manifest = fs.readFileSync(manifestPath, 'utf8');

if (manifest.includes(MARKER)) {
  console.log(
    '[native-patch] AndroidManifest.xml already registers documents.'
  );
  process.exit(0);
}

// Insert after the launcher filter, inside the same <activity>.
const anchor = `            <intent-filter>
                <action android:name="android.intent.action.MAIN" />
                <category android:name="android.intent.category.LAUNCHER" />
            </intent-filter>
`;

if (!manifest.includes(anchor)) {
  console.error(
    '[native-patch] Could not find the launcher intent-filter in AndroidManifest.xml.\n' +
      '               Capacitor may have changed its template - patch it by hand.'
  );
  process.exit(1);
}

fs.writeFileSync(manifestPath, manifest.replace(anchor, anchor + filters()));
console.log(
  `[native-patch] Registered ${MIME_TYPES.length} document types for open-with and share.`
);
